package com.contextgraph.controller; import com.contextgraph.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/dashboard") public class DashboardController{final UserRepository users;final DocumentRepository docs;final EntityNodeRepository entities;public DashboardController(UserRepository u,DocumentRepository d,EntityNodeRepository e){users=u;docs=d;entities=e;}@GetMapping("/summary")public Map<String,Object>summary(Authentication a){Long id=users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();return Map.of("informationItems",docs.findByOwnerIdOrderByCreatedAtDesc(id).size(),"connectedEntities",entities.findByOwnerId(id).size(),"contextGroups",0,"status","ready");}}